CREATE TABLE IF NOT EXISTS user_sessions (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, workspace_id CHAR(36) NOT NULL, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_session(user_id,revoked_at,expires_at), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(workspace_id) REFERENCES workspaces(id));
CREATE TABLE IF NOT EXISTS purchase_receipts (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, purchase_order_id CHAR(36) NOT NULL, received_by CHAR(36) NOT NULL, received_at DATETIME NOT NULL, idempotency_key VARCHAR(120) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_receipt_idempotency(workspace_id,idempotency_key), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(purchase_order_id) REFERENCES purchase_orders(id), FOREIGN KEY(received_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS purchase_receipt_lines (id CHAR(36) PRIMARY KEY, receipt_id CHAR(36) NOT NULL, purchase_order_line_id CHAR(36) NOT NULL, quantity_received INT NOT NULL, batch_id CHAR(36), CHECK(quantity_received>0), FOREIGN KEY(receipt_id) REFERENCES purchase_receipts(id), FOREIGN KEY(purchase_order_line_id) REFERENCES purchase_order_lines(id), FOREIGN KEY(batch_id) REFERENCES expiry_batches(id));
CREATE TABLE IF NOT EXISTS idempotency_records (id CHAR(36) PRIMARY KEY, workspace_id CHAR(36) NOT NULL, user_id CHAR(36) NOT NULL, idempotency_key VARCHAR(120) NOT NULL, operation VARCHAR(60) NOT NULL, resource_id CHAR(36) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_operation_idempotency(workspace_id,idempotency_key,operation), FOREIGN KEY(workspace_id) REFERENCES workspaces(id), FOREIGN KEY(user_id) REFERENCES users(id));
